import React, { useState } from "react";
import "./AnimatedHoloSkills.css";

const skillGroups = {
  "Languages & Databases": ["Python","R","SQL","PostgreSQL","C","C++","Java","JavaScript","MongoDB"],
  "Web Development": ["React","Node.js","Express.js","HTML","CSS","Flask","REST API","FastAPI"],
  "Machine Learning & AI": ["TensorFlow","PyTorch","Scikit‑learn","Transformers","OpenCV","NLTK","Tesseract OCR","BERT","DistilBERT","T5","LLMs","Deep Learning","Reinforcement Learning"],
  "Data & Analytics": ["Power BI","Tableau","Google Data Studio","Microsoft Fabric","PySpark"],
  "Tools": ["Visual Studio","Eclipse","Git","GitHub","JIRA","Postman","PyCharm","Excel","Word","PowerPoint"]
};

export default function SkillsTabs() {
  const categories = Object.keys(skillGroups);
  const [active, setActive] = useState(categories[0]);

  return (
    <section className="skills-tabs">
      {/* <h1>My Skills</h1> */}
      <div className="tabs">
        {categories.map(cat => (
          <button
            key={cat}
            className={`tab ${active===cat?"active":""}`}
            onClick={()=>setActive(cat)}
          >{cat}</button>
        ))}
      </div>
      <div className="tab-body">
        {skillGroups[active].map(skill=>(
          <span key={skill} className="pill">{skill}</span>
        ))}
      </div>
    </section>
  );
}
