import React, { useEffect, useState } from "react";

const words = ["GenAI", "LLMs", "Transformers", "Deep Learning Frameworks", "Advanced ML algorithms"];

// Speeds and Pauses (in ms)
const TYPING_SPEED = 100;      // how fast characters are typed
const BACKSPACE_SPEED = 80;    // how fast characters are deleted
const PAUSE_AFTER_TYPE = 1500; // pause after a word is fully typed
const PAUSE_AFTER_DELETE = 500; // pause after a word is fully deleted

const RotatingWords = () => {
  const [wordIndex, setWordIndex] = useState(0);     // which word we are on
  const [charIndex, setCharIndex] = useState(0);     // how many characters of the current word are typed
  const [isDeleting, setIsDeleting] = useState(false);
  const [typedText, setTypedText] = useState("");
  const [typingSpeed, setTypingSpeed] = useState(TYPING_SPEED);

  useEffect(() => {
    const currentWord = words[wordIndex];
    // Build typed text from the current word using charIndex
    setTypedText(currentWord.slice(0, charIndex));
  }, [charIndex, wordIndex]);

  useEffect(() => {
    // Main typing logic
    const currentWord = words[wordIndex];

    // If we're not deleting, type forward
    if (!isDeleting) {
      // If we haven't finished typing the current word
      if (charIndex < currentWord.length) {
        const timeoutId = setTimeout(() => {
          setCharIndex(charIndex + 1);
        }, typingSpeed);
        return () => clearTimeout(timeoutId);
      } else {
        // Word fully typed
        // Pause, then start deleting
        const timeoutId = setTimeout(() => {
          setIsDeleting(true);
          setTypingSpeed(BACKSPACE_SPEED);
        }, PAUSE_AFTER_TYPE);
        return () => clearTimeout(timeoutId);
      }
    } else {
      // Deleting
      if (charIndex > 0) {
        // Still have characters to delete
        const timeoutId = setTimeout(() => {
          setCharIndex(charIndex - 1);
        }, typingSpeed);
        return () => clearTimeout(timeoutId);
      } else {
        // Word fully deleted
        // Pause, then move to the next word
        const timeoutId = setTimeout(() => {
          setIsDeleting(false);
          setTypingSpeed(TYPING_SPEED);
          setWordIndex((prev) => (prev + 1) % words.length);
        }, PAUSE_AFTER_DELETE);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [charIndex, isDeleting, typingSpeed, wordIndex]);

  return <span className="rotating-words">{typedText}</span>;
};

export default RotatingWords;
