// Contact.js
import React from "react";
import "./Contact.css";
import { FaGithub, FaLinkedin } from "react-icons/fa";

const Contact = () => {
  return (
    <div className="contact-container">
      <div className="particle-bg"></div>
      <div className="contact-panel">
        <h1>Contact Me</h1>
        <p className="intro-text">
          I'd love to hear from you! Whether you have a question or just want to connect, feel free to reach out.
        </p>

        {/* Personal Info Section */}
        <div className="personal-info">
          <h2>Get in Touch</h2>
          <ul className="info-list">
            <li><strong>Location:</strong> Buffalo, New York, USA</li>
            <li><strong>Email:</strong> pprajakta1406@gmail.com</li>
            <li><strong>University Email:</strong> ppatil23@buffalo.edu</li>
            <li><strong>Phone:</strong> +1 (716) 416-8604</li>
          </ul>
          <h3>Connect with Me</h3>
          <div className="button-group">
            <a
              href="https://github.com/PatilPrajakta14"
              target="_blank"
              rel="noopener noreferrer"
              className="btn social-btn"
            >
              <FaGithub className="social-icon" />
            </a>
            <a
              href="https://www.linkedin.com/in/prajakta-patil-cs/"
              target="_blank"
              rel="noopener noreferrer"
              className="btn social-btn"
            >
              <FaLinkedin className="social-icon" />
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Contact;
