function highlightColon(text) {
  const i = text.indexOf(":");
  if (i === -1) return text;
  return (
    <>
      <span className="highlight-before-colon">{text.slice(0, i + 1)}</span>
      {text.slice(i + 1)}
    </>
  );
}

