const categories = [
  "All",
  "Machine Learning & AI",
  "Web & Full‑Stack Development",
  "Data & Analytics Platforms"
];

const ProjectsTimeline = () => {
  const [expandedIndex, setExpandedIndex] = useState(null);
  const [activeCat, setActiveCat] = useState("All");
  const [showImagesFor, setShowImagesFor] = useState(null);

  const toggleExpand = (i) => {
    setExpandedIndex(expandedIndex === i ? null : i);
    setShowImagesFor(null);
  };

  const filtered = projectData.filter((p) =>
    activeCat === "All" 
      ? true 
      : p.category.includes(activeCat)
  );

  return (
    <div className="projects-timeline-container">
      <h1 className="timeline-title">Projects</h1>

      <div className="filter-bar">
        {categories.map((cat) => (
          <button
            key={cat}
            className={`filter-pill ${activeCat === cat ? "active" : ""}`}
            onClick={() => {
              setActiveCat(cat);
              setExpandedIndex(null);
              setShowImagesFor(null);
            }}
          >
            {cat}
          </button>
        ))}
      </div>

      <div className="timeline">
        {filtered.map((project, idx) => (
          <div
            key={project.title}
            className="timeline-item"
            onClick={() => toggleExpand(idx)}
          >
            <div className="timeline-marker" />
            <div className="timeline-content">
              <div className="timeline-header">
                <h2 className="project-title">{project.title}</h2>
                <span className="project-date">{project.date}</span>
              </div>

              {expandedIndex === idx && (
                <div className="project-details">
                  <ul>
                    {project.details.map((d, i) => (
                      <li key={i}>{highlightColon(d)}</li>
                    ))}
                  </ul>
                  <div className="links-section">
                    {project.links.certificate && (
                      <a
                        href={project.links.certificate}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="doc-btn"
                      >
                        🏆 View Certificate
                      </a>
                    )}
                    {project.links.blog && (
                      <a
                        href={project.links.blog}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="doc-btn"
                      >
                        ✍️ Read Blog
                      </a>
                    )}
                    {project.links.copyright && (
                      <a
                        href={project.links.copyright}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="doc-btn"
                      >
                        ©️ View Copyright
                      </a>
                    )}
                    {project.links.github && (
                      <a
                        href={project.links.github}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="doc-btn"
                      >
                        💻 View on GitHub
                      </a>
                    )}
                    {/* Hackathon Highlights link */}
                    {/* {project.images && project.images.length > 0 && (
                      <a
                        href="#hackathon-images"
                        className="doc-btn"
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          setShowImagesFor(showImagesFor === idx ? null : idx);
                        }}
                      >
                        🖼️ Hackathon Highlights
                      </a>
                    )} */}
                  </div>

                  {/* image grid toggles below
                  {showImagesFor === idx && (
                    <div className="images-grid">
                      {project.images.map((src, i) => (
                        <div key={i} className="hack-img-container">
                          <img
                            src={src}
                            alt={`${project.title} ${i + 1}`}
                            className="hack-img"
                        />
                      </div>
                    ))}
                  </div>
                )} */}
                </div>
              )}
            </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <p className="no-projects">No projects found in this category.</p>
        )}
      </div>
    </div>
  );
};

export default ProjectsTimeline;
