// InternshipTimeline.js
import React, { useState } from "react";
import "./Internship.css";

const internshipData = [
  {
    title: "NVIDIA",
    date: "Jan 2024 - July 2024",
    location: "Bangalore, India",
    companyInfo: "NVIDIA is a global pioneer in AI computing and GPUs, fueling next-generation breakthroughs in data centers, gaming, automotive, and more. With a passion for pushing boundaries, NVIDIA fosters a culture of innovation that shapes the future of technology.",
    details: [
      "Implemented a Python script to automate drive updates, reducing operational errors by 80% and saving 100 hours of manual work monthly.",
      "Automated test cases by reviewing JIRA and analyzing templates, enhancing testing efficiency and speeding up project deliverables by 30%.",
      "Utilized Python and SQL for scripting and database management, processing over 500,000 data points monthly."
    ],
    certificateLink: "https://drive.google.com/file/d/1Q0SfNHt_hZyPmApO_0VnqdzwQ2HfVOyi/view?usp=sharing"
  },
  {
    title: "TIAA",
    date: "June 2023 - July 2023",
    location: "Pune, India",
    companyInfo:"TIAA (Teachers Insurance and Annuity Association of America) is a financial services organization primarily serving individuals in academia, research, healthcare, and government sectors, offering retirement planning, investing, and insurance solutions. ",
    details: [
      "Engineered REST APIs using Java and Spring Boot, facilitating secure and efficient access to customer data for over 100 team members, improving decision-making by 25%.",
      "Created a centralized API management system aligning data access protocols, enabling a 25% increase in data accuracy and empowering the team with real-time insights."
    ],
    certificateLink: "https://drive.google.com/file/d/1e8x24DPRh44XOxQfFYf3tRxiyRqa9pqT/view?usp=sharing"
  },
  {
    title: "HAL (Hindustan Aeronautics Limited)",
    date: "Feb 2023 - Mar 2023",
    location: "Nashik, India",
    companyInfo:"Hindustan Aeronautics Limited (HAL), an Indian public sector aerospace and defense company, designs, develops, manufactures, repairs, and overhauls aircraft, helicopters, engines, and related systems for both military and civilian applications. ",
    details: [
      "Analyzed a large volume of data available on the HAL’s IFS ERP website to understand and evaluate system functionalities.",
      "Explored HAL’s IFS ERP system, gaining hands-on experience with computer networking and server management, facilitating the management of over 500 network devices",
      "Conducted an in-depth evaluation of firewall configurations and secure network systems; identified potential security gaps and provided recommendations, which could reduce unauthorized access attempts by 40\%"
    ],
    certificateLink: "https://drive.google.com/file/d/1LpyDLzNwNDmAZLbX96XYoNBQMjQSDYrU/view?usp=sharing"
  },
  {
    title: "Cognifront",
    date: "Jan 2023 - Feb 2023",
    location: "Remote, India",
    companyInfo:"Cognifront, headquartered in Nashik, India, is a company that develops and provides industrial technology solutions, e-learning tools, and software, with a focus on transforming technical education. ",
    details: [
      "Optimized performance and usability of web applications by integrating technologies like HTML, CSS, JavaScript, PHP, MySQL, AJAX, and JSON, contributing to a 20% increase in client engagement",
      "Migrated over 50 complex computer graphics algorithms from C to JavaScript, enhancing cross-platform compatibility and reducing code execution time by 15%"
    ],
    certificateLink: "https://drive.google.com/file/d/1N3HDaGqDWg2LyRJxlO5hCw_eskRPfI80/view?usp=sharing"
  }
];

const InternshipTimeline = () => {
  const [expandedIndex, setExpandedIndex] = useState(null);

  const toggleExpand = (index) => {
    setExpandedIndex(expandedIndex === index ? null : index);
  };

  return (
    <div className="internship-container">
      <h1 className="internship-title">Internship Experiences</h1>
      <div className="timeline">
        {internshipData.map((internship, index) => (
          <div
            key={index}
            className="timeline-item"
            onClick={() => toggleExpand(index)}
          >
            <div className="timeline-marker"></div>
            <div className="timeline-content">
              <div className="timeline-header">
                <h2 className="project-title">{internship.title}</h2>
                <span className="project-date">{internship.date}</span>
              </div>
              <p className="location">{internship.location}</p>
              {expandedIndex === index && (
                <div className="project-details">
                  {/* Company info paragraph */}
                  {internship.companyInfo && (
                    <p className="company-info">{internship.companyInfo}</p>
                  )}
                   <h3 className="my-tasks-heading">My Missions at {internship.title}</h3>
    
                    <ul className="my-tasks-list">
                    {internship.details.map((detail, idx) => {
                      const colonIndex = detail.indexOf(":");
                      return (
                        <li key={idx}>
                          {colonIndex !== -1 ? (
                            <>
                              <span className="highlight-before-colon">
                                {detail.slice(0, colonIndex + 1)}
                              </span>
                              {detail.slice(colonIndex + 1)}
                            </>
                          ) : (
                            detail
                          )}
                        </li>
                      );
                    })}
                  </ul>
                  <div className="links-section">
                    {internship.certificateLink && (
                      <a
                        href={internship.certificateLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="doc-btn"
                      >
                        🏆 View Internship Completion Certificate
                      </a>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default InternshipTimeline;
